nst dot = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n      if (i === 0) dot.classList.add(\'active\');\\r\\n      dot.addEventListener(\'click\', () => goToSlide(i));\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"_element_width\":\"initial\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"5bf0d5c\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":30,\"column\":\"30\",\"row\":\"0\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"be69dd9\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\"