ousel-track\');\\r\\n    const slides = Array.from(track.children);\\r\\n    const nextButton = document.querySelector(\'.carousel-button.next\');\\r\\n    const prevButton = document.querySelector(\'.carousel-button.prev\');\\r\\n    const dotsNav = document.querySelector(\'.carousel-dots\');\\r\\n\\r\\n    let currentIndex = 0;\\r\\n\\r\\n    \\/\\/ Criar bolinhas dinamicamente\\r\\n    slides.forEach((_, i) => {\\r\\n      const dot = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n      if (i === 0) dot.classList.add(\'active\');\\r\\n      dot.addEventListener(\'click\', () => goToSlide(i));\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"0424637\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\"},\"elements\":[{\"id\":\"81001cd\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[icones_servicos_uerj]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false}]'),(2813,411,'_elementor_edit_mode','builder'),(2814,411,'_elementor_template_type','wp-page'),(2815,411,'_elementor_version','3.32.1'),(2816,411,'_wp_page_template','elementor_header_footer'),(2817,411,'_elementor_data','[{\"id\":\"8b71430\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"boxed_width\":{\"unit\":\"px\",\"size\":1600,\"sizes\":[]},\"min_height\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"flex_justify_content\":\"center\",\"animation\":\"fadeIn\",\"presetTitle\":\"Cont\\u00eainer\",\"presetIcon\":\"eicon-container\"},\"elements\":[{\"id\":\"ad27683\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!DOCTYPE html>\\r\\n<html lang=\\\"pt-BR\\\">\\r\\n<head>\\r\\n  <meta charset=\\\"UTF-8\\\">\\r\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\r\\n  <title>Carrossel Responsivo<\\/title>\\r\\n  <style>\\r\\n    * {\\r\\n      box-sizing: border-box;\\r\\n      margin: 0;\\r\\n      padding: 0;\\r\\n    }\\r\\n\\r\\n    body {\\r\\n      font-family: Arial, sans-serif;\\r\\n      background: #f4f4f4;\\r\\n    }\\r\\n\\r\\n    .carousel {\\r\\n      position: relative;\\r\\n      width: 100%;\\r\\n      height: 500px; \\/* \\ud83d\\udd39 Ajuste a altura aqui *\\/\\r\\n      overflow: hidden;\\r\\n    }\\r\\n\\r\\n    .carousel-track {\\r\\n      display: flex;\\r\\n      transition: transform 0.5s ease-in-out;\\r\\n      height: 100%;\\r\\n    }\\r\\n\\r\\n    .carousel-slide {\\r\\n      min-width: 100%;\\r\\n      height: 100%;\\r\\n      background-size: cover;      \\/* \\ud83d\\udd39 Preenche sempre todo o container *\\/\\r\\n      background-position: center; \\/* \\ud83d\\udd39 Centraliza *\\/\\r\\n      background-repeat: no-repeat;\\/* \\ud83d\\udd39 Evita repeti\\u00e7\\u00e3o *\\/\\r\\n    }\\r\\n\\r\\n    \\/* \\ud83d\\udd39 Bot\\u00f5es de navega\\u00e7\\u00e3o *\\/\\r\\n    .carousel-button {\\r\\n      position: absolute;\