\\r\\n    }\\r\\n\\r\\n    \\/* Carrossel full width *\\/\\r\\n    .carousel {\\r\\n      position: relative;\\r\\n      width: 100vw;\\r\\n      height: 500px;\\r\\n      overflow: hidden;\\r\\n      background: #000;\\r\\n\\r\\n      \\/* faz o carrossel sair do limite central e encostar nas laterais *\\/\\r\\n      margin-left: calc(50% - 50vw);\\r\\n      margin-right: calc(50% - 50vw);\\r\\n    }\\r\\n\\r\\n    .carousel-track {\\r\\n      display: flex;\\r\\n      transition: transform 0.5s ease-in-out;\\r\\n      height: 100%;\\r\\n    }\\r\\n\\r\\n    .carousel-slide {\\r\\n      min-width: 100%;\\r\\n      height: 100%;\\r\\n      background-size: cover;\\r\\n      background-position: center;\\r\\n      background-repeat: no-repeat;\\r\\n      position: relative;\\r\\n    }\\r\\n\\r\\n    .carousel-caption {\\r\\n      position: absolute;\\r\\n      left: 0;\\r\\n      bottom: 0;\\r\\n      width: 100%;\\r\\n      background: rgba(0, 0, 0, 0.65);\\r\\n      color: #fff;\\r\\n      padding: 20px 25px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption h3 {\\r\\n      font-size: 1.4rem;\\r\\n      margin-bottom: 8px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption p {\\r\\n      font-size: 1rem;\\r\\n      line-height: 1.5;\\r\\n    }\\r\\n\\r\\n    .carousel-button {\\r\\n      position: absolute;\\r\\n      top: 50%;\\r\\n      transform: translateY(-50%);\\r\\n      background: rgba(0,0,0,0.5);\\r\\n      border: none;\\r\\n      color: #fff;\\r\\n      font-size: 2rem;\\r\\n      padding: 0.5rem 1rem;\\r\\n      cursor: pointer;\\r\\n      border-radius: 50%;\\r\\n      z-index: 10;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-button:hover {\\r\\n      background: rgba(0,0,0,0.8);\\r\\n    }\\r\\n\\r\\n    .carousel-button.prev {\\r\\n      left: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-button.next {\\r\\n      right: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-dots {\\r\\n      position: absolute;\\r\\n      bottom: 100px;\\r\\n      