 padding: 0 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-title {\\r\\n      color: #003BB1;\\r\\n      text-align: center;\\r\\n      margin: 0;\\r\\n      font-family: inherit;\\r\\n      font-size: 2.5rem;\\r\\n      font-weight: 700;\\r\\n      line-height: 1.2;\\r\\n    }\\r\\n\\r\\n    .carousel {\\r\\n      position: relative;\\r\\n      width: 100vw;\\r\\n      height: 500px;\\r\\n      overflow: hidden;\\r\\n      background: #000;\\r\\n      margin-left: calc(50% - 50vw);\\r\\n      margin-right: calc(50% - 50vw);\\r\\n    }\\r\\n\\r\\n    .carousel-track {\\r\\n      display: flex;\\r\\n      transition: transform 0.5s ease-in-out;\\r\\n      height: 100%;\\r\\n    }\\r\\n\\r\\n    .carousel-slide {\\r\\n      min-width: 100%;\\r\\n      height: 100%;\\r\\n      background-size: cover;\\r\\n      background-position: center;\\r\\n      background-repeat: no-repeat;\\r\\n      position: relative;\\r\\n      display: block;\\r\\n      text-decoration: none;\\r\\n      color: inherit;\\r\\n      cursor: pointer;\\r\\n    }\\r\\n\\r\\n    .carousel-slide::after {\\r\\n      content: \\\"\\\";\\r\\n      position: absolute;\\r\\n      inset: 0;\\r\\n      background: rgba(0, 0, 0, 0.15);\\r\\n      transition: background 0.3s ease;\\r\\n    }\\r\\n\\r\\n    .carousel-slide:hover::after {\\r\\n      background: rgba(0, 0, 0, 0.05);\\r\\n    }\\r\\n\\r\\n    .carousel-caption {\\r\\n      position: absolute;\\r\\n      left: 0;\\r\\n      bottom: 0;\\r\\n      width: 100%;\\r\\n      background: rgba(0, 0, 0, 0.65);\\r\\n      color: #fff;\\r\\n      padding: 20px 25px;\\r\\n      z-index: 2;\\r\\n      transition: background 0.3s ease;\\r\\n    }\\r\\n\\r\\n    .carousel-slide:hover .carousel-caption {\\r\\n      background: rgba(0, 0, 0, 0.78);\\r\\n    }\\r\\n\\r\\n    .carousel-caption h3 {\\r\\n      font-size: 1.4rem;\\r\\n      margin-bottom: 8px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption p {\\r\\n      font-size: 1rem;\\r\\n      line-height: 1.5;\\r\\n   